import {getLanguage} from './i18n.mjs';
const rw=(th,en)=>getLanguage()==='en'?en:th;
export const FAILURE_CASES=[['offline','อินเทอร์เน็ตหลุด','Internet outage'],['printer','เครื่องพิมพ์ขัดข้อง','Printer failure'],['kds','จอครัวขัดข้อง','Kitchen display failure'],['payment','ไม่ทราบผลชำระเงิน','Payment outcome unknown'],['normal','ระบบปกติ','Normal operation']];
export function createFailure(caseId='offline'){
 if(!FAILURE_CASES.some(x=>x[0]===caseId))throw Error('Unknown scenario');
 const count={offline:3,printer:4,kds:2,payment:4,normal:4}[caseId],orders=Array.from({length:count},(_,i)=>({id:'SIM-ORDER-'+String(i+1).padStart(3,'0'),amount:180,cost:95,attempts:0,ack:false,payment:caseId==='payment'?'unknown':'confirmed'}));
 const s={caseId,recovered:caseId==='normal',orders,ledger:{},duplicates:0,conflicts:0,paymentRequests:caseId==='payment'?4:0,printDone:0,logs:[]};
 if(['normal','printer','kds'].includes(caseId))for(const o of orders){insertSale(s,o);o.ack=true;o.attempts=1;}
 if(caseId==='normal')s.printDone=4;
 return s;
}
export function insertSale(s,event){const old=s.ledger[event.id];if(old){if(old.amount!==event.amount||old.cost!==event.cost){s.conflicts++;return 'conflict';}s.duplicates++;return 'duplicate';}s.ledger[event.id]={id:event.id,amount:event.amount,cost:event.cost};return 'inserted';}
export function recoverFailure(s){if(s.recovered)return s;s.recovered=true;
 if(s.caseId==='offline'){s.orders.forEach((o,i)=>{o.attempts++;insertSale(s,o);o.ack=i!==0;});s.logs.push('lost-ack');}
 if(s.caseId==='payment'){s.orders.forEach((o,i)=>{o.payment=i===3?'declined':'confirmed';if(o.payment==='confirmed'){o.attempts++;insertSale(s,o);o.ack=true;}});s.logs.push('provider-status');}
 if(s.caseId==='printer'){s.printDone=4;s.logs.push('print-only');}
 if(s.caseId==='kds')s.logs.push('kds-resume');
 s.logs.push('recovered');return s;
}
export function retryFailure(s){if(!s.recovered)return s;const pending=s.orders.filter(o=>!o.ack&&o.payment==='confirmed'),replay=pending.length?pending:s.orders.filter(o=>o.payment==='confirmed').slice(0,1);for(const o of replay){o.attempts++;const result=insertSale(s,o);if(result!=='conflict')o.ack=true;}s.logs.push('retry-same-id');return s;}
export function failureMetrics(s){const n=Object.keys(s.ledger).length,pending=s.orders.filter(o=>!o.ack&&o.payment==='confirmed').length,wait={offline:s.recovered?8:12,printer:s.recovered?4:6,kds:s.recovered?7:14,payment:s.recovered?6:11,normal:4}[s.caseId],extra={offline:100,printer:50,kds:170,payment:20,normal:0}[s.caseId],delivered=s.caseId==='payment'?(s.recovered?3:0):s.caseId==='kds'?(s.recovered?2:0):s.orders.length,unknown=s.caseId==='payment'&&!s.recovered,profit=unknown?null:delivered*85-extra;
 return{unique:n,centralOrderValue:n*180,pending,printPending:s.caseId==='printer'&&!s.recovered?4:0,kitchenPending:s.caseId==='kds'&&!s.recovered?2:0,paymentPending:unknown?4:0,attempts:s.orders.reduce((v,o)=>v+o.attempts,0),delivered,wait,extra,profit,delta:profit===null?null:profit-340,lost:unknown?null:4-s.orders.length+(s.caseId==='payment'?1:0),revenue:delivered*180,cost:delivered*95};
}
let failureState=createFailure();
export function getFailureState(){return failureState;}
export function failureVisual(event){const s=failureState,m=failureMetrics(s),failed=!s.recovered;return{haltCloud:failed&&s.caseId==='offline',blockNode:failed&&s.caseId==='kds'?'kds':failed&&s.caseId==='payment'&&event==='sale'?'sys-pos':null,bufferNode:s.caseId==='offline'?'gateway':s.caseId==='printer'?'printer':s.caseId==='kds'?'kds':s.caseId==='payment'?'payment':null,pending:m.pending+m.printPending+m.kitchenPending+m.paymentPending};}
const rm=n=>new Intl.NumberFormat(getLanguage()==='en'?'en-GB':'th-TH',{maximumFractionDigits:0}).format(n);
export function renderReliability(){const s=failureState,m=failureMetrics(s),money=n=>n===null?rw('รอยืนยัน','Pending'):'฿'+rm(n),queue={offline:rw('outbox เข้ารหัสบน POS / gateway ในร้าน','Encrypted POS / gateway outbox in store'),printer:rw('คิวพิมพ์ใน local agent แยกจากคิวขาย','Local-agent print queue, separate from sales'),kds:rw('คิวงานครัวตาม order ID และขั้นตอน SOP','Kitchen queue keyed by order ID and SOP step'),payment:rw('ตาราง payment_pending รอผู้ให้บริการยืนยัน','payment_pending table awaiting provider confirmation'),normal:rw('คิวว่าง ระบบยืนยันแล้ว','Queue empty; acknowledgments received')}[s.caseId];
 return `<section class="panel activity resilience-panel"><div class="panel-header"><h2>${rw('เมื่อระบบขัดข้อง ข้อมูลและกำไรเปลี่ยนอย่างไร','When systems fail: queues, sales and profit')}</h2><span class="tiny-tag">${rw('สถานการณ์สมมติ · ลูกค้าเป้าหมาย 4 ราย','Synthetic scenario · 4 potential customers')}</span></div><div class="resilience-controls"><label for="failure-case">${rw('เลือกเหตุขัดข้อง','Failure scenario')}</label><select id="failure-case">${FAILURE_CASES.map(([id,th,en])=>`<option value="${id}" ${id===s.caseId?'selected':''}>${rw(th,en)}</option>`).join('')}</select><button id="failure-recover" class="button button-primary" ${s.recovered?'disabled':''}>${s.caseId==='payment'?rw('ตรวจผลกับผู้ให้บริการ','Reconcile with provider'):rw('กู้คืนและส่งคิว','Restore and flush queue')}</button><button id="failure-retry" class="button button-white" ${!s.recovered?'disabled':''}>${rw('ทดสอบส่งซ้ำด้วยรหัสเดิม','Test replay with same ID')}</button><button id="failure-reset" class="button button-white">${rw('เริ่มสถานการณ์ใหม่','Restart scenario')}</button></div>
 <div class="resilience-status"><strong>${rw('จุดพักข้อมูล','Buffer location')}: ${queue}</strong><p>${rw('สถานะ','State')}: ${s.recovered?rw('ระบบกู้คืนแล้ว','Recovered'):rw('กำลังขัดข้อง','Failure active')} · ${rw('รอ ACK','Awaiting ACK')}: ${m.pending} · ${rw('คิวพิมพ์','Print queue')}: ${m.printPending} · ${rw('คิวครัว','Kitchen queue')}: ${m.kitchenPending} · ${rw('รอผลชำระ','Payment pending')}: ${m.paymentPending}</p><p>${rw('นี่คือแบบจำลองคิวในหน่วยความจำ รีเฟรชแล้วเริ่มใหม่ ระบบจริงต้องใช้พื้นที่เก็บถาวรและทดสอบการกู้คืน ไอคอนคิวบนภาพเป็นจำนวนจำลอง ไม่ใช่ข้อมูลจริง','This is an in-memory queue model and resets on reload. Production needs durable storage and recovery tests. Canvas queue counts are synthetic.')}</p></div>
 <div class="resilience-metrics">${[[rw('ครั้งที่ส่งเข้าระบบกลาง','Central delivery attempts'),m.attempts],[rw('ออเดอร์ไม่ซ้ำในระบบกลาง','Unique central orders'),m.unique],[rw('ข้อความซ้ำที่ตัดทิ้ง','Duplicate messages suppressed'),s.duplicates],[rw('มูลค่าออเดอร์ยืนยันในระบบกลาง','Confirmed central order value'),money(m.centralOrderValue)]].map(([title,value])=>`<div><span>${title}</span><strong>${value}</strong></div>`).join('')}</div>
 <div class="resilience-table"><table class="insight-table"><thead><tr><th>${rw('รหัสเหตุการณ์คงเดิม','Stable event ID')}</th><th>${rw('ส่งแล้ว','Attempts')}</th><th>ACK</th><th>${rw('ผลชำระ','Payment')}</th></tr></thead><tbody>${s.orders.map(o=>`<tr><td>${o.id}</td><td>${o.attempts}</td><td>${o.ack?'✓':'—'}</td><td>${o.payment==='unknown'?rw('ยังไม่ทราบ','Unknown'):o.payment==='declined'?rw('ไม่อนุมัติ','Declined'):rw('ยืนยันแล้ว','Confirmed')}</td></tr>`).join('')}</tbody></table></div>
 <div class="resilience-explanation"><h3>${rw('ส่งซ้ำได้ แต่ยอดขายไม่ซ้ำ','Retry delivery without duplicating a sale')}</h3><p>${rw('บันทึกออเดอร์กับ outbox ในธุรกรรมเดียวกัน → ส่ง event ID เดิม → เซิร์ฟเวอร์ตรวจ unique key และเนื้อหาข้อความ → บันทึกครั้งเดียวพร้อมผลตอบกลับ → ลบงานค้างเมื่อได้ ACK เท่านั้น เนื้อหาต่างแต่ใช้รหัสเดิมต้องปฏิเสธ ไม่ใช่เขียนทับ','Commit the order and outbox atomically → resend the same event ID → enforce a unique key and verify the payload → commit once and return the prior result → remove pending work only after ACK. Reject a conflicting payload with the same ID.')}</p><p>${s.logs.includes('lost-ack')?rw('ตัวอย่างนี้ส่งถึงเซิร์ฟเวอร์แล้ว แต่ ACK ของออเดอร์แรกหาย จึงเหลืองานค้าง 1 รายการ กดทดสอบส่งซ้ำ: จำนวนครั้งส่งเพิ่ม แต่จำนวนออเดอร์และมูลค่าเดิมไม่เพิ่ม','The first order reached the server but its ACK was lost, leaving one pending item. Replay increases delivery attempts, not unique orders or order value.'):rw('การพิมพ์ซ้ำและทำงานครัวต่อใช้คิวงานแยก ไม่สร้างออเดอร์หรือเรียกเก็บเงินใหม่','Print retries and kitchen recovery use separate work queues, not new orders or payment charges.')}</p>${s.caseId==='payment'?`<p>${rw('ห้ามกดชำระใหม่เมื่อผลยังไม่ทราบ ต้องตรวจสถานะหรือ webhook ที่ตรวจลายเซ็นกับผู้ให้บริการ ในตัวอย่างนี้คำขอชำระคงอยู่ที่ 4 ครั้ง หลังตรวจพบสำเร็จ 3 และไม่อนุมัติ 1 การส่งเหตุการณ์ซ้ำไม่เรียกเก็บเพิ่ม','Do not submit another charge when the outcome is unknown. Reconcile provider status or a signed webhook. This example keeps payment requests at 4; reconciliation confirms 3 and declines 1. Event replay does not charge again.')} · ${rw('คำขอชำระ','Payment requests')}: <strong id="failure-payment-requests">${s.paymentRequests}</strong></p>`:''}</div>
 <div class="resilience-impact"><h3>${rw('ผลต่อกำไรและบริการ: เทียบสมมติฐานระบบปกติ','Profit and service impact: compared with an assumed normal case')}</h3><div class="resilience-metrics">${[[rw('กำไรส่วนเกินหลังค่าใช้จ่ายเพิ่ม','Contribution after incremental costs'),money(m.profit)],[rw('ผลต่างจากกรณีปกติ ฿340','Difference from normal ฿340'),money(m.delta)],[rw('เวลารอเฉลี่ย','Average wait'),m.wait+' '+rw('นาที','minutes')],[rw('ส่งมอบแล้ว','Delivered'),m.delivered+' / 4']].map(([title,value])=>`<div><span>${title}</span><strong>${value}</strong></div>`).join('')}</div><p>${rw('สมมติราคาต่อรายการ 180 ต้นทุนผันแปร 95 บาท กรณีปกติส่งมอบ 4 ราย = 340 บาท กรณีนี้รายได้จากงานส่งมอบ','Assume THB 180 price and THB 95 variable cost. Normal delivery to 4 customers contributes THB 340. This case: delivered revenue')} ${money(m.revenue)} − ${rw('ต้นทุน','cost')} ${money(m.cost)} − ${rw('ค่าแรงเพิ่ม/แก้ไข/ของเสีย','extra labor / repair / waste')} ${money(m.extra)} = <strong id="failure-profit">${money(m.profit)}</strong></p><p>${rw('ยอดในระบบกลางอาจล่าช้า ไม่ได้แปลว่ายอดขายหาย เน็ตกลับไม่ได้กู้ลูกค้าที่เลิกซื้อหรือคืนค่าเสียหายที่เกิดแล้ว กรณีจอครัวขัดข้อง เงินรับล่วงหน้าไม่ถือเป็นรายได้งานส่งมอบจนกว่าจะทำเสร็จ กรณีไม่ทราบผลชำระยังไม่สรุปกำไร','A delayed central report is not necessarily a lost sale. Recovery does not bring back abandoned purchases or erase incurred costs. With KDS failure, advance payment is not delivered revenue until fulfillment. Unknown payment outcomes leave profit unresolved.')}</p><p>${rw('ตัวเลขเป็นผลจากสมมติฐาน ไม่ใช่กำไรส่วนเพิ่มเชิงเหตุจาก A/B ก่อนขยายจริงต้องเทียบกลุ่มควบคุม เก็บการยกเลิก ของเสีย งานซ้ำ และเวลาคิวให้ครบ','These are assumption-based impacts, not causal A/B incremental profit. Real rollout needs controls and complete cancellations, waste, duplicate work and queue metrics.')}</p><button class="button button-white" data-nav="ab">${rw('ไปหน้าทดลอง A/B','Open A/B experiments')}</button></div></section>`;
}
export function renderFailureQuick(){const s=failureState,m=failureMetrics(s);return `<section class="panel resilience-quick"><div class="resilience-controls"><label for="failure-quickcase">${rw('ทดลองความขัดข้องบนภาพ 3D','Try a failure on the 3D view')}</label><select id="failure-quickcase">${FAILURE_CASES.map(([id,th,en])=>`<option value="${id}" ${id===s.caseId?'selected':''}>${rw(th,en)}</option>`).join('')}</select><button id="failure-quickrecover" class="button button-primary" ${s.recovered?'disabled':''}>${rw('กู้คืน / ตรวจผล','Recover / reconcile')}</button><button id="failure-quickretry" class="button button-white" ${!s.recovered?'disabled':''}>${rw('ส่งรหัสเดิมซ้ำ','Replay same ID')}</button><button id="failure-details" class="button button-white">${rw('ดูคิวและผลต่อกำไร','Queue and profit details')}</button><p>${rw('รอ ACK','Awaiting ACK')}: ${m.pending} · ${rw('ออเดอร์ไม่ซ้ำในระบบกลาง','Unique central orders')}: ${m.unique} · ${rw('ตัดข้อความซ้ำ','Duplicates suppressed')}: ${s.duplicates} · ${rw('เส้นประแดง = ส่งต่อไม่ได้ ป้าย QUEUE = จุดพักงาน','Red dashes = blocked delivery; QUEUE badge = pending work')}</p></div></section>`;}
export function mountReliability(root,rerender,onScenario){root.querySelectorAll('#failure-case,#failure-quickcase').forEach(el=>el.addEventListener('change',e=>{failureState=createFailure(e.target.value);onScenario(failureState.caseId);rerender();}));root.querySelectorAll('#failure-recover,#failure-quickrecover').forEach(el=>el.addEventListener('click',()=>{recoverFailure(failureState);rerender();}));root.querySelectorAll('#failure-retry,#failure-quickretry').forEach(el=>el.addEventListener('click',()=>{retryFailure(failureState);rerender();}));root.querySelector('#failure-reset').addEventListener('click',()=>{failureState=createFailure(failureState.caseId);rerender();});root.querySelector('#failure-details').addEventListener('click',()=>root.querySelector('.resilience-panel').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}));}
